  async function refresh(){if(!session)return;try{const sessionResponse=await api('/session');if(sessionResponse.ok){const current=await sessionResponse.json();session={...session,isAdmin:current.isAdmin,taskAccess:current.taskAccess||{}};sessionStorage.setItem(SESSION_KEY,JSON.stringify(session));}const requests=[api('/profile').then(async response=>{if(response.ok)profile=(await response.json()).profile;}),api('/support').then(async response=>{if(response.ok)supportTickets=(await response.json()).tickets||[];}),can('site.orders.view')?api('/orders').then(async response=>{if(response.ok){const result=await response.json();orders=result.orders||[];projects=(result.projectRecords||(result.projects||[]).map(name=>({id:'',name,address:'',notes:'',active:true}))).filter(project=>project.active!==false);localStorage.setItem(PROJECTS_KEY,JSON.stringify(projects));}}):Promise.resolve(),can('site.cnc.view')?api('/site/cnc').then(async response=>{if(response.ok)cncPanels=(await response.json()).cncPanels||[];}):Promise.resolve()];await Promise.all(requests);}catch{message='Showing saved information. Connect to refresh.';}}
